domain FloatMath {
  function clamp(x: Real, minv: Real, maxv: Real): Real
  axiom forall x: Real, minv: Real, maxv: Real :: minv <= maxv ==> minv <= clamp(x, minv, maxv) && clamp(x, minv, maxv) <= maxv
  function sqrtf(x: Real): Real
  axiom forall x: Real :: x >= 0.0 ==> sqrtf(x) >= 0.0
  function f32FromInt(i: Int): Real
  axiom forall i: Int :: f32FromInt(i) == ite(i >= 0, i as Real, 0.0)
  function isNanF(x: Real): Bool
  function isInfF(x: Real): Bool
}

function stableHash(bytes: Seq[Int], seed: Int): Int
function minInt(a: Int, b: Int): Int { ite(a < b, a, b) }
function maxInt(a: Int, b: Int): Int { ite(a > b, a, b) }

predicate validRanker(r: Ref) {
  acc(r.ranker_ngram_weights) && acc(r.ranker_lsh_hash_params) && acc(r.ranker_num_hash_functions) && acc(r.ranker_num_ngrams) && acc(r.ranker_seed) && acc(r.ranker_allocator)
}

predicate validTensor(t: Ref) {
  acc(t.tensor_data) && acc(t.tensor_shape)
}

predicate validBitSet(b: Ref) {
  acc(b.bitset_bits)
}

predicate validRankedSegment(s: Ref) {
  acc(s.ranked_tokens) && acc(s.ranked_score) && acc(s.ranked_position) && acc(s.ranked_anchor)
}

method Ranker_init(allocator: Ref, num_ngrams: Int, num_hash_funcs: Int, seed: Int) returns (res: Ref)
requires num_ngrams > 0
requires num_hash_funcs > 0
ensures validRanker(res)
ensures |res.ranker_ngram_weights| == num_ngrams
ensures |res.ranker_lsh_hash_params| == num_hash_funcs * 2
{
  res := new()
  res.ranker_ngram_weights := Seq[Real](num_ngrams)
  res.ranker_lsh_hash_params := Seq[Int](num_hash_funcs * 2)
  res.ranker_num_hash_functions := num_hash_funcs
  res.ranker_num_ngrams := num_ngrams
  res.ranker_seed := seed
  res.ranker_allocator := allocator
  var i: Int := 0
  while (i < num_ngrams)
  invariant 0 <= i && i <= num_ngrams
  invariant acc(res.ranker_ngram_weights)
  {
    var decay: Real := 1.0 / f32FromInt(i + 1)
    res.ranker_ngram_weights := res.ranker_ngram_weights[0..i] ++ Seq[Real](decay) ++ res.ranker_ngram_weights[i+1..]
    i := i + 1
  }
  i := 0
  while (i < num_hash_funcs)
  invariant 0 <= i && i <= num_hash_funcs
  invariant acc(res.ranker_lsh_hash_params)
  {
    var i_u64: Int := i
    var i_plus_one: Int := i + 1
    var ha: Int := seed + (i_u64 * 0x9e3779b97f4a7c15)
    var hb: Int := seed + (i_plus_one * 0x517cc1b727220a95)
    res.ranker_lsh_hash_params := res.ranker_lsh_hash_params[0..(i*2)] ++ Seq[Int](ha) ++ Seq[Int](hb) ++ res.ranker_lsh_hash_params[(i*2 + 2)..]
    i := i + 1
  }
}

method Ranker_deinit(self: Ref)
requires validRanker(self)
ensures !acc(self.ranker_ngram_weights)
ensures !acc(self.ranker_lsh_hash_params)
{
}

method scoreSequence(self: Ref, tokens: Seq[Int], ssi: Ref) returns (res: Real)
requires validRanker(self)
requires |tokens| >= 0
ensures 0.0 <= res && res <= 1.0
{
  if (|tokens| == 0) {
    res := 0.0
    return
  }
  var ngram_score: Real := 0.0
  var gram: Int := 1
  while (gram < minInt(self.ranker_num_ngrams, |tokens| + 1))
  invariant 1 <= gram && gram <= minInt(self.ranker_num_ngrams, |tokens| + 1) + 1
  invariant acc(self.ranker_ngram_weights)
  {
    if (|tokens| >= gram) {
      var start: Int := 0
      while (start < |tokens| - gram + 1)
      invariant 0 <= start && start <= |tokens| - gram + 1
      {
        var ngram: Seq[Int] := tokens[start..start + gram]
        var h: Int := stableHash(ngram, self.ranker_seed)
        ngram_score := ngram_score + 0.0
        start := start + 1
      }
    }
    gram := gram + 1
  }
  var diversity_score: Real := computeTokenDiversity(self, tokens)
  var proximity: Real := anchorProximity(self, tokens, ssi)
  var raw_score: Real := ngram_score + 0.3 * diversity_score + 0.3 * proximity
  raw_score := FloatMath.clamp(raw_score, 0.0, 100.0)
  res := raw_score / 100.0
}

method scoreSequenceWithQuery(self: Ref, tokens: Seq[Int], query: Seq[Int], ssi: Ref) returns (res: Real)
requires validRanker(self)
ensures 0.0 <= res && res <= 1.0
{
  var base_score: Real := scoreSequence(self, tokens, ssi)
  var token_overlap: Real := computeTokenOverlap(self, tokens, query)
  var jaccard: Real := computeJaccardSimilarity(self, tokens, query)
  var combined_score: Real := base_score * 0.4 + token_overlap * 0.3 + jaccard * 0.3
  res := FloatMath.clamp(combined_score, 0.0, 1.0)
}

method computeTokenDiversity(self: Ref, tokens: Seq[Int]) returns (res: Real)
requires |tokens| >= 0
{
  if (|tokens| == 0) {
    res := 0.0
    return
  }
  var unique_count: Int := 0
  var i: Int := 0
  while (i < |tokens|)
  invariant 0 <= i && i <= |tokens|
  {
    unique_count := unique_count + 1
    i := i + 1
  }
  res := f32FromInt(unique_count) / f32FromInt(|tokens|)
}

method computeTokenOverlap(self: Ref, tokens: Seq[Int], query: Seq[Int]) returns (res: Real)
{
  if (|tokens| == 0 || |query| == 0) {
    res := 0.0
    return
  }
  var overlap: Int := 0
  var i: Int := 0
  while (i < |tokens|)
  invariant 0 <= i && i <= |tokens|
  {
    var j: Int := 0
    var found: Bool := false
    while (j < |query| && !found)
    invariant 0 <= j && j <= |query|
    {
      if (tokens[i] == query[j]) {
        found := true
        overlap := overlap + 1
      }
      j := j + 1
    }
    i := i + 1
  }
  var max_len: Int := maxInt(|tokens|, |query|)
  res := f32FromInt(overlap) / f32FromInt(max_len)
}

method computeJaccardSimilarity(self: Ref, tokens: Seq[Int], query: Seq[Int]) returns (res: Real)
{
  if (|tokens| == 0 && |query| == 0) {
    res := 1.0
    return
  }
  if (|tokens| == 0 || |query| == 0) {
    res := 0.0
    return
  }
  var intersection: Int := 0
  var union_size: Int := 0
  var i: Int := 0
  while (i < |tokens|)
  invariant 0 <= i && i <= |tokens|
  {
    union_size := union_size + 1
    var j: Int := 0
    while (j < |query|)
    invariant 0 <= j && j <= |query|
    {
      if (tokens[i] == query[j]) {
        intersection := intersection + 1
      }
      j := j + 1
    }
    i := i + 1
  }
  if (union_size == 0) {
    res := 0.0
  } else {
    res := f32FromInt(intersection) / f32FromInt(union_size)
  }
}

method anchorProximity(self: Ref, tokens: Seq[Int], ssi: Ref) returns (res: Real)
{
  if (|tokens| == 0) {
    res := 0.0
    return
  }
  var anchors: Int := 0
  var total_dist: Real := 0.0
  var i: Int := 0
  while (i < |tokens|)
  invariant 0 <= i && i <= |tokens|
  invariant anchors >= 0
  invariant total_dist >= 0.0
  {
    var pos: Int := i
    if (false) {
      anchors := anchors + 1
      var raw_dist: Int := 0
      var clamped_dist: Int := minInt(raw_dist, 4294967295)
      total_dist := total_dist + f32FromInt(clamped_dist)
    }
    i := i + 1
  }
  if (anchors == 0) {
    res := 0.0
    return
  }
  var denominator: Real := f32FromInt(anchors) * f32FromInt(|tokens|)
  if (denominator <= 0.0) {
    denominator := 1.0
  }
  var clamped: Real := clamp(total_dist / denominator, 0.0, 1.0)
  res := 1.0 - clamped
}

