method batchScore(self: Ref, sequences: Seq[Seq[Int]], ssi: Ref, allocator: Ref) returns (scores: Seq[Real])
requires validRanker(self)
{
  if (|sequences| == 0) {
    scores := Seq[Real](0)
    return
  }
  scores := Seq[Real](|sequences|)
  var b: Int := 0
  while (b < |sequences|)
  invariant 0 <= b && b <= |sequences|
  invariant acc(scores)
  {
    scores := scores[0..b] ++ Seq(scoreSequence(self, sequences[b], ssi)) ++ scores[b+1..]
    b := b + 1
  }
}

method minHashSignature(self: Ref, tokens: Seq[Int]) returns (sig: Seq[Int])
requires validRanker(self)
ensures |sig| == self.ranker_num_hash_functions
{
  if (|tokens| == 0) {
    sig := Seq[Int](self.ranker_num_hash_functions)
    return
  }
  sig := Seq[Int](self.ranker_num_hash_functions)
  var h: Int := 0
  while (h < self.ranker_num_hash_functions)
  invariant 0 <= h && h <= self.ranker_num_hash_functions
  invariant acc(sig)
  {
    var min_hash: Int := 18446744073709551615
    var seed_a: Int := self.ranker_lsh_hash_params[h * 2]
    var seed_b: Int := self.ranker_lsh_hash_params[h * 2 + 1]
    var t: Int := 0
    while (t < |tokens|)
    invariant 0 <= t && t <= |tokens|
    {
      var hash_val: Int := stableHash(Seq[Int](tokens[t]), seed_a) ^ seed_b
      if (hash_val < min_hash) {
        min_hash := hash_val
      }
      t := t + 1
    }
    sig := sig[0..h] ++ Seq(min_hash) ++ sig[h+1..]
    h := h + 1
  }
}

method jaccardSimilarityFromSignatures(sig1: Seq[Int], sig2: Seq[Int]) returns (res: Real)
{
  if (|sig1| != |sig2| || |sig1| == 0) {
    res := 0.0
    return
  }
  var matches: Int := 0
  var i: Int := 0
  while (i < |sig1|)
  invariant 0 <= i && i <= |sig1|
  {
    if (sig1[i] == sig2[i]) {
      matches := matches + 1
    }
    i := i + 1
  }
  res := f32FromInt(matches) / f32FromInt(|sig1|)
}

method estimateJaccard(set1: Ref, set2: Ref) returns (res: Real)
requires validBitSet(set1) && validBitSet(set2)
{
  var intersect: Int := 0
  var union_count: Int := 0
  var words: Int := minInt(|set1.bitset_bits|, |set2.bitset_bits|)
  var i: Int := 0
  while (i < words)
  invariant 0 <= i && i <= words
  {
    intersect := intersect + 0
    union_count := union_count + 0
    i := i + 1
  }
  if (union_count == 0) {
    res := 0.0
  } else {
    res := f32FromInt(intersect) / f32FromInt(union_count)
  }
}

method vectorScore(embedding: Ref, query_emb: Ref) returns (res: Real)
requires validTensor(embedding) && validTensor(query_emb)
{
  if (|embedding.tensor_data| == 0) {
    res := 0.0
    return
  }
  var dot_prod: Real := 0.0
  var norm_emb: Real := 0.0
  var norm_query: Real := 0.0
  var len: Int := |embedding.tensor_data|
  var i: Int := 0
  while (i < len)
  invariant 0 <= i && i <= len
  invariant dot_prod >= -10000.0 && dot_prod <= 10000.0
  {
    var e: Real := embedding.tensor_data[i]
    var q: Real := query_emb.tensor_data[i]
    if (!isNanF(e) && !isNanF(q) && !isInfF(e) && !isInfF(q)) {
      dot_prod := dot_prod + e * q
      norm_emb := norm_emb + e * e
      norm_query := norm_query + q * q
    }
    i := i + 1
  }
  if (norm_emb <= 0.0 || norm_query <= 0.0) {
    res := 0.0
    return
  }
  norm_emb := sqrtf(norm_emb)
  norm_query := sqrtf(norm_query)
  if (norm_emb == 0.0 || norm_query == 0.0) {
    res := 0.0
    return
  }
  res := clamp(dot_prod / (norm_emb * norm_query), -1.0, 1.0)
}

method dotProductScore(embedding: Ref, query_emb: Ref) returns (res: Real)
requires validTensor(embedding) && validTensor(query_emb)
{
  if (|embedding.tensor_data| == 0) {
    res := 0.0
    return
  }
  var dot_prod: Real := 0.0
  var len: Int := |embedding.tensor_data|
  var i: Int := 0
  while (i < len)
  invariant 0 <= i && i <= len
  {
    var e: Real := embedding.tensor_data[i]
    var q: Real := query_emb.tensor_data[i]
    if (!isNanF(e) && !isNanF(q) && !isInfF(e) && !isInfF(q)) {
      dot_prod := dot_prod + e * q
    }
    i := i + 1
  }
  res := dot_prod
}

method weightedAverage(scores: Seq[Real], weights: Seq[Real]) returns (res: Real)
requires |scores| == |weights|
{
  if (|scores| == 0) {
    res := 0.0
    return
  }
  var num: Real := 0.0
  var den: Real := 0.0
  var i: Int := 0
  while (i < |scores|)
  invariant 0 <= i && i <= |scores|
  {
    var s: Real := scores[i]
    var w: Real := weights[i]
    if (!isNanF(s) && !isNanF(w) && !isInfF(s) && !isInfF(w)) {
      num := num + s * w
      den := den + w
    }
    i := i + 1
  }
  if (den == 0.0) {
    res := 0.0
  } else {
    res := num / den
  }
}

method exponentialDecay(scores: Seq[Real], decay_factor: Real)
{
  if (|scores| == 0 || decay_factor <= 0.0 || decay_factor >= 1.0) {
    return
  }
  var current_decay: Real := 1.0
  var i: Int := 0
  while (i < |scores|)
  invariant 0 <= i && i <= |scores|
  {
    scores := scores[0..i] ++ Seq[Real](scores[i] * current_decay) ++ scores[i+1..]
    current_decay := current_decay * decay_factor
    i := i + 1
  }
}

method normalizeScoresStatic(scores: Seq[Real])
{
  if (|scores| == 0) {
    return
  }
  var min_score: Real := 1e30
  var max_score: Real := -1e30
  var valid_count: Int := 0
  var i: Int := 0
  while (i < |scores|)
  invariant 0 <= i && i <= |scores|
  {
    var s: Real := scores[i]
    if (!isNanF(s) && !isInfF(s)) {
      valid_count := valid_count + 1
      if (s < min_score) {
        min_score := s
      }
      if (s > max_score) {
        max_score := s
      }
    }
    i := i + 1
  }
  if (valid_count == 0) {
    return
  }
  if (max_score == min_score) {
    i := 0
    while (i < |scores|)
    invariant 0 <= i && i <= |scores|
    {
      var s: Real := scores[i]
      if (!isNanF(s) && !isInfF(s)) {
        scores := scores[0..i] ++ Seq[Real](0.5) ++ scores[i+1..]
      }
      i := i + 1
    }
    return
  }
  var range: Real := max_score - min_score
  i := 0
  while (i < |scores|)
  invariant 0 <= i && i <= |scores|
  {
    var s: Real := scores[i]
    if (!isNanF(s) && !isInfF(s)) {
      scores := scores[0..i] ++ Seq[Real]((s - min_score) / range) ++ scores[i+1..]
    }
    i := i + 1
  }
}

method rankByMultipleCriteria(self: Ref, candidates: Seq[Ref], criteria: Seq[Seq[Real]], weights: Seq[Real], allocator: Ref)
requires validRanker(self)
{
  if (|candidates| == 0 || |criteria| == 0 || |weights| == 0) {
    return
  }
  var num_cand: Int := |candidates|
  var num_crit: Int := minInt(|criteria|, |weights|)
  var combined: Seq[Real] := Seq[Real](num_cand)
  var c: Int := 0
  while (c < num_cand)
  invariant 0 <= c && c <= num_cand
  invariant acc(combined)
  {
    var crit_score: Real := 0.0
    var cr: Int := 0
    while (cr < num_crit)
    invariant 0 <= cr && cr <= num_crit
    {
      if (c < |criteria[cr]|) {
        var score_val: Real := criteria[cr][c]
        var weight_val: Real := weights[cr]
        if (!isNanF(score_val) && !isNanF(weight_val) && !isInfF(score_val) && !isInfF(weight_val)) {
          crit_score := crit_score + score_val * weight_val
        }
      }
      cr := cr + 1
    }
    combined := combined[0..c] ++ Seq(crit_score) ++ combined[c+1..]
    c := c + 1
  }
}

