method calibrateWeights(self: Ref, training_data: Seq[Seq[Int]], labels: Seq[Real], ssi: Ref, epochs: Int)
requires validRanker(self)
requires |training_data| == |labels|
{
  if (|training_data| == 0 || |labels| == 0) {
    return
  }
  var gradients: Seq[Real] := Seq[Real](|self.ranker_ngram_weights|)
  var epoch: Int := 0
  while (epoch < epochs)
  invariant 0 <= epoch && epoch <= epochs
  {
    var i: Int := 0
    while (i < |training_data|)
    invariant 0 <= i && i <= |training_data|
    {
      i := i + 1
    }
    updateWeights(self, gradients)
    epoch := epoch + 1
  }
}

method updateWeights(self: Ref, gradients: Seq[Real])
requires validRanker(self)
{
  var i: Int := 0
  while (i < minInt(|self.ranker_ngram_weights|, |gradients|))
  invariant 0 <= i && i <= minInt(|self.ranker_ngram_weights|, |gradients|)
  invariant acc(self.ranker_ngram_weights)
  {
    var grad: Real := gradients[i]
    if (!isNanF(grad) && !isInfF(grad)) {
      var new_val: Real := self.ranker_ngram_weights[i] + grad * 0.01
      self.ranker_ngram_weights := self.ranker_ngram_weights[0..i] ++ Seq(clamp(new_val, 0.0, 1.0)) ++ self.ranker_ngram_weights[i+1..]
    }
    i := i + 1
  }
}

