requires num_hash_funcs > 0
ensures validRanker(res)
ensures |res.ranker_ngram_weights| == num_ngrams
ensures |res.ranker_lsh_hash_params| == num_hash_funcs * 2
{
  res := new()
  res.ranker_ngram_weights := Seq[Real](num_ngrams)
  res.ranker_lsh_hash_params := Seq[Int](num_hash_funcs * 2)
  res.ranker_num_hash_functions := num_hash_funcs
  res.ranker_num_ngrams := num_ngrams
  res.ranker_seed := seed
  res.ranker_allocator := allocator
